### 3. CODIFICAÇÃO EM JAVA

```java
import java.io.InputStream;
import java.io.IOException;
import java.util.Arrays;

public class Main {

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0;
        private int len = 0;

        public FastScanner(InputStream in) {
            this.in = in;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                ptr = 0;
                len = in.read(buffer);
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        public int nextInt() throws IOException {
            int c = read();
            while (c <= ' ' && c != -1) c = read();
            if (c == -1) return -1;
            boolean neg = false;
            if (c == '-') {
                neg = true;
                c = read();
            }
            int res = 0;
            while (c >= '0' && c <= '9') {
                res = res * 10 + (c - '0');
                c = read();
            }
            return neg ? -res : res;
        }
    }

    public static void main(String[] args) throws IOException {
        FastScanner scanner = new FastScanner(System.in);
        int n = scanner.nextInt();
        if (n <= 0) {
            System.out.println(0);
            return;
        }

        int[] x = new int[n + 1];
        int[] y = new int[n + 1];

        for (int i = 1; i <= n; i++) {
            x[i] = scanner.nextInt();
            y[i] = scanner.nextInt();
        }

        // Número total de arestas: N arestas do Palácio (0) + N*(N-1)/2 arestas entre tendas
        int totalEdges = n + (int) (((long) n * (n - 1)) / 2);
        long[] edges = new long[totalEdges];
        int edgeCount = 0;

        // Arestas do Palácio Real (vértice 0) para cada tenda
        for (int i = 1; i <= n; i++) {
            long d = (long) x[i] * x[i] + (long) y[i] * y[i];
            edges[edgeCount++] = (d << 24) | (0L << 12) | i;
        }

        // Arestas entre todos os pares de tendas
        for (int i = 1; i <= n; i++) {
            for (int j = i + 1; j <= n; j++) {
                long dx = x[i] - x[j];
                long dy = y[i] - y[j];
                long d = dx * dx + dy * dy;
                edges[edgeCount++] = (d << 24) | ((long) i << 12) | j;
            }
        }

        // Ordenação crescente por distância ao quadrado
        Arrays.sort(edges);

        int[] dp = new int[n + 1];
        int[] cand = new int[n + 1];
        int[] touched = new int[n + 1];
        int ans = 0;

        int i = 0;
        while (i < edgeCount) {
            int j = i;
            long curD = edges[i] >>> 24;

            // Encontra o intervalo [i, j) com arestas de mesma distância D
            while (j < edgeCount && (edges[j] >>> 24) == curD) {
                j++;
            }

            int touchedCount = 0;

            // 1º Passo: Avaliar as arestas de distância curD usando valores de dp de distâncias < curD
            for (int k = i; k < j; k++) {
                long e = edges[k];
                int u = (int) ((e >>> 12) & 0xFFF);
                int v = (int) (e & 0xFFF);

                if (u == 0) {
                    // Aresta saindo do Palácio para a tenda v
                    int treats = 1 + dp[v];
                    if (treats > ans) {
                        ans = treats;
                    }
                } else {
                    // Aresta entre a tenda u e a tenda v
                    int candU = 1 + dp[v];
                    int candV = 1 + dp[u];

                    if (cand[u] == 0) touched[touchedCount++] = u;
                    if (cand[v] == 0) touched[touchedCount++] = v;

                    if (candU > cand[u]) cand[u] = candU;
                    if (candV > cand[v]) cand[v] = candV;
                }
            }

            // 2º Passo: Efetivar as atualizações na DP para as tendas modificadas
            for (int k = 0; k < touchedCount; k++) {
                int node = touched[k];
                if (cand[node] > dp[node]) {
                    dp[node] = cand[node];
                }
                cand[node] = 0; // Limpeza para o próximo grupo
            }

            i = j;
        }

        System.out.println(ans);
    }
}
```

